           verifier.VerifyString(COORDINATE_SYSTEM_NAME()) &&
           VerifyField<int32_t>(verifier, VT_CENTRAL_BODY_ID, 4) &&
           VerifyOffset(verifier, VT_SITE_ID) &&
           verifier.VerifyString(SITE_ID()) &&
           VerifyOffset(verifier, VT_SECOND_OBJECT_ID) &&
           verifier.VerifyString(SECOND_OBJECT_ID()) &&
           VerifyOffset(verifier, VT_OWNER_OBJECT_ID) &&
           verifier.VerifyString(OWNER_OBJECT_ID()) &&
           VerifyOffset(verifier, VT_OWNER_HARDWARE_NAME) &&
           verifier.VerifyString(OWNER_HARDWARE_NAME()) &&
           VerifyOffset(verifier, VT_TIME_SYSTEM) &&
           verifier.VerifyString(TIME_SYSTEM()) &&
           verifier.EndTable();
