  void UnPackTo(PCEParameterRefT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<PCEParameterRef> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const PCEParameterRefT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
