inline ::flatbuffers::Offset<PCEParameterRef> CreatePCEParameterRef(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    pceParameter PARAMETER = pceParameter::UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> PROVIDER_DEFINED_NAME = 0,
    int32_t ELEMENT_INDEX = -1,
    ::flatbuffers::Offset<::flatbuffers::String> COORDINATE_SYSTEM_NAME = 0,
    int32_t CENTRAL_BODY_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SITE_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SECOND_OBJECT_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> OWNER_OBJECT_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> OWNER_HARDWARE_NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> TIME_SYSTEM = 0) {
  PCEParameterRefBuilder builder_(_fbb);
  builder_.add_TIME_SYSTEM(TIME_SYSTEM);
  builder_.add_OWNER_HARDWARE_NAME(OWNER_HARDWARE_NAME);
  builder_.add_OWNER_OBJECT_ID(OWNER_OBJECT_ID);
  builder_.add_SECOND_OBJECT_ID(SECOND_OBJECT_ID);
  builder_.add_SITE_ID(SITE_ID);
  builder_.add_CENTRAL_BODY_ID(CENTRAL_BODY_ID);
  builder_.add_COORDINATE_SYSTEM_NAME(COORDINATE_SYSTEM_NAME);
  builder_.add_ELEMENT_INDEX(ELEMENT_INDEX);
  builder_.add_PROVIDER_DEFINED_NAME(PROVIDER_DEFINED_NAME);
  builder_.add_PARAMETER(PARAMETER);
  return builder_.Finish();
}

