inline const PCE *GetPCE(const void *buf) {
  return ::flatbuffers::GetRoot<PCE>(buf);
}

inline const PCE *GetSizePrefixedPCE(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<PCE>(buf);
}

inline const char *PCEIdentifier() {
  return "$PCE";
}

inline bool PCEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PCEIdentifier());
}

inline bool SizePrefixedPCEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PCEIdentifier(), true);
}

template <bool B = false>
inline bool VerifyPCEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<PCE>(PCEIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedPCEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<PCE>(PCEIdentifier());
}

inline void FinishPCEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PCE> root) {
  fbb.Finish(root, PCEIdentifier());
}

inline void FinishSizePrefixedPCEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PCE> root) {
  fbb.FinishSizePrefixed(root, PCEIdentifier());
}

inline std::unique_ptr<PCET> UnPackPCE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PCET>(GetPCE(buf)->UnPack(res));
}

inline std::unique_ptr<PCET> UnPackSizePrefixedPCE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PCET>(GetSizePrefixedPCE(buf)->UnPack(res));
}

#endif  // FLATBUFFERS_GENERATED_PCE_MAIN_H_
